import { useMemo, useState } from "react";
import { Button, FieldFrame, PageHeader, RecordList, Select, StatusPill, Typography } from "@autograph/components";
import { RecordDetailPanel, RecordListDetailLayout } from "@autograph/compositions";

type Severity = "Critical" | "Low";
type Product = {
  id: string; name: string; sku: string; location: string; severity: Severity;
  onHand: number; reorderPoint: number; inbound: number; supplier: string;
  leadTime: string; casePack: number; unitCost: string; lastOrder: string;
};

const products: Product[] = [
  { id: "p1", name: "Organic Oat Milk 1L", sku: "DRY-1048", location: "Downtown", severity: "Critical", onHand: 4, reorderPoint: 24, inbound: 0, supplier: "Northstar Foods", leadTime: "3 business days", casePack: 12, unitCost: "$2.18", lastOrder: "Aug 28, 2026" },
  { id: "p2", name: "Sea Salt Kettle Chips", sku: "SNK-2214", location: "Downtown", severity: "Low", onHand: 18, reorderPoint: 30, inbound: 12, supplier: "Harbor Snacks", leadTime: "5 business days", casePack: 18, unitCost: "$1.06", lastOrder: "Sep 1, 2026" },
  { id: "p3", name: "Free-Range Eggs 12ct", sku: "CLD-0302", location: "Airport", severity: "Critical", onHand: 2, reorderPoint: 16, inbound: 0, supplier: "Meadowbrook Farms", leadTime: "2 business days", casePack: 6, unitCost: "$3.42", lastOrder: "Aug 30, 2026" },
  { id: "p4", name: "Sparkling Water Lime 8pk", sku: "BEV-8831", location: "Airport", severity: "Low", onHand: 10, reorderPoint: 20, inbound: 8, supplier: "Clear Spring Beverage", leadTime: "4 business days", casePack: 4, unitCost: "$4.90", lastOrder: "Aug 26, 2026" },
  { id: "p5", name: "Whole Bean Coffee 340g", sku: "DRY-7710", location: "Northside", severity: "Critical", onHand: 3, reorderPoint: 15, inbound: 0, supplier: "Atlas Roasters", leadTime: "6 business days", casePack: 8, unitCost: "$7.25", lastOrder: "Aug 24, 2026" },
];

export default function StockExceptionsScreen() {
  const [location, setLocation] = useState("all");
  const [severity, setSeverity] = useState("all");
  const [selectedId, setSelectedId] = useState("p1");
  const [drafted, setDrafted] = useState<Record<string, boolean>>({});
  const visible = useMemo(() => products.filter((p) => (location === "all" || p.location === location) && (severity === "all" || p.severity === severity)), [location, severity]);
  const selected = visible.find((p) => p.id === selectedId);
  const updateFilter = (nextLocation: string, nextSeverity: string) => {
    setLocation(nextLocation); setSeverity(nextSeverity);
    const next = products.filter((p) => (nextLocation === "all" || p.location === nextLocation) && (nextSeverity === "all" || p.severity === nextSeverity));
    if (!next.some((p) => p.id === selectedId)) setSelectedId(next[0]?.id ?? "");
  };
  return (
    <main className="min-h-screen bg-[var(--color-bg-page)] p-[var(--space-6)] text-[var(--color-text-primary)]">
      <div className="mx-auto grid max-w-[var(--size-content-wide)] gap-[var(--space-5)]">
        <PageHeader title="Stock Exceptions" subtitle="Review products below their reorder point and simulate the next replenishment." />
        <section aria-label="Exception filters" className="flex flex-wrap items-end gap-[var(--space-3)] rounded-[var(--radius-panel)] border border-[var(--color-border-subtle)] bg-[var(--color-bg-surface)] p-[var(--space-4)]">
          <FieldFrame label="Location" className="min-w-[12rem] flex-1">
            <Select aria-label="Location" value={location} options={[{value:"all",label:"All locations"},{value:"Downtown",label:"Downtown"},{value:"Airport",label:"Airport"},{value:"Northside",label:"Northside"}]} onValueChange={(value) => updateFilter(value, severity)} />
          </FieldFrame>
          <FieldFrame label="Severity" className="min-w-[12rem] flex-1">
            <Select aria-label="Severity" value={severity} options={[{value:"all",label:"All severities"},{value:"Critical",label:"Critical"},{value:"Low",label:"Low"}]} onValueChange={(value) => updateFilter(location, value)} />
          </FieldFrame>
          <Typography variant="caption" tone="secondary" className="mb-[var(--space-2)]">{visible.length} of {products.length} exceptions</Typography>
        </section>
        <RecordListDetailLayout
          hasSelection={Boolean(selected)} selectedId={selectedId || undefined} onBack={() => setSelectedId("")} backLabel="Back to exceptions"
          list={<RecordList ariaLabel="Low-stock products" heading="Low-stock products" summary="On hand / reorder point" selectedId={selectedId} onSelect={setSelectedId} emptyState="No exceptions match these filters." items={visible.map((p) => ({ id:p.id, primary:p.name, secondary:`${p.sku} · ${p.location}`, trailing:<><StatusPill label={p.severity} tone={p.severity === "Critical" ? "danger" : "warning"} size="xs" /><strong>{p.onHand} / {p.reorderPoint}</strong></> }))} />}
          detail={selected ? <RecordDetailPanel
            className="max-h-[calc(100vh-var(--space-8))]"
            title={selected.name} subtitle={`${selected.sku} · ${selected.location}`}
            status={{label:selected.severity,tone:selected.severity === "Critical" ? "danger" : "warning"}}
            metadata={[{id:"supplier",label:"Supplier",value:selected.supplier},{id:"lead",label:"Lead time",value:selected.leadTime}]}
            sections={[
              {id:"stock",title:"Stock position",collapsible:false,items:[
                {type:"field",id:"on-hand",label:"On hand",value:`${selected.onHand} units`},
                {type:"field",id:"reorder",label:"Reorder point",value:`${selected.reorderPoint} units`},
                {type:"field",id:"inbound",label:"Inbound",value:`${selected.inbound} units`},
                {type:"note",id:"risk",title:"Exception remains open",body:`On-hand stock is ${selected.reorderPoint-selected.onHand} units below the reorder point. A mock action does not change inventory.`,tone:selected.severity === "Critical" ? "danger" : "warning"}
              ]},
              {id:"supplier-details",title:"Supplier details",items:[
                {type:"field",id:"supplier-name",label:"Supplier",value:selected.supplier},
                {type:"field",id:"lead-time",label:"Lead time",value:selected.leadTime},
                {type:"field",id:"case-pack",label:"Case pack",value:`${selected.casePack} units`},
                {type:"field",id:"unit-cost",label:"Unit cost",value:selected.unitCost},
                {type:"field",id:"last-order",label:"Last order",value:selected.lastOrder}
              ]},
              ...(drafted[selected.id] ? [{id:"mock-result",title:"Mock replenishment",collapsible:false,items:[{type:"note" as const,id:"drafted-note",title:"Simulation ready",body:`A mock order for ${Math.ceil((selected.reorderPoint*2-selected.onHand)/selected.casePack)*selected.casePack} units (${Math.ceil((selected.reorderPoint*2-selected.onHand)/selected.casePack)} cases) is staged for review. No order was sent and stock was not changed.`,tone:"info" as const}]}] : [])
            ]}
            actions={drafted[selected.id] ? [{id:"reset",label:"Reset mock",intent:"secondary"}] : [{id:"replenish",label:"Try mock replenishment",intent:"primary"}]}
            onAction={(id) => setDrafted((state) => ({...state,[selected.id]:id === "replenish"}))}
          /> : null}
        />
      </div>
    </main>
  );
}
